      'import { authTables } from "@convex-dev/auth/server";\nimport { defineSchema, defineTable } from "convex/server";\nimport { v } from "convex/values";\n\nexport default defineSchema({\n  ...authTables,\n  todos: defineTable({\n    userId: v.id("users"),\n    text: v.string(),\n    done: v.boolean(),\n    createdAt: v.number(),\n  })\n    .index("by_created_at", ["createdAt"])\n    .index("by_user_created_at", ["userId", "createdAt"]),\n  guestNames: defineTable({\n    name: v.string(),\n    userId: v.id("users"),\n    createdAt: v.number(),\n  })\n    .index("by_name", ["name"])\n    .index("by_user", ["userId"]),\n});\n',
    "convex/todos.ts":
      'import { getAuthUserId } from "@convex-dev/auth/server";\nimport type { Auth } from "convex/server";\nimport type { Id } from "./_generated/dataModel";\nimport { mutation, query } from "./_generated/server";\nimport { v } from "convex/values";\n\nconst { array, boolean, id, null: nullValue, number, object, string, union } = v;\n\nconst MAX_TODOS_PER_USER = 50;\nconst MAX_VISIBLE_TODOS = 50;\nconst MAX_TODO_TEXT_LENGTH = 280;\n\nconst vTodo = object({\n  _id: id("todos"),\n  creatorName: string(),\n  text: string(),\n  done: boolean(),\n  viewerCanToggle: boolean(),\n});\n\nconst listResultValidator = object({\n  todos: array(vTodo),\n  viewerTodoCount: union(number(), nullValue()),\n});\nconst createResultValidator = nullValue();\nconst toggleResultValidator = nullValue();\n\nasync function getRequiredUserId(ctx: { auth: Auth }) {\n  const userId = await getAuthUserId(ctx);\n  if (!userId) {\n    throw new Error("Not authenticated");\n  }\n  return userId;\n}\n\nexport const list = query({\n  args: {},\n  returns: listResultValidator,\n  handler: async (ctx) => {\n    const todos = await ctx.db\n      .query("todos")\n      .withIndex("by_created_at")\n      .order("desc")\n      .take(MAX_VISIBLE_TODOS);\n    const viewerUserId = await getAuthUserId(ctx);\n    const creatorNames = new Map<Id<"users">, string>();\n    let viewerTodoCount: number | null = null;\n\n    for (const todo of todos) {\n      if (creatorNames.has(todo.userId)) {\n        continue;\n      }\n\n      const user = await ctx.db.get(todo.userId);\n      creatorNames.set(todo.userId, user?.name ?? "Guest");\n    }\n\n    if (viewerUserId) {\n      const viewerTodos = await ctx.db\n        .query("todos")\n        .withIndex("by_user_created_at", (q) => q.eq("userId", viewerUserId))\n        .order("desc")\n        .take(MAX_TODOS_PER_USER);\n      viewerTodoCount = viewerTodos.length;\n    }\n\n    return {\n      todos: todos.map((todo) => ({\n        _id: todo._id,\n        creatorName: creatorNames.get(todo.userId) ?? "Guest",\n        text: todo.text,\n        done: todo.done,\n        viewerCanToggle: viewerUserId === todo.userId,\n      })),\n      viewerTodoCount,\n    };\n  },\n});\n\nexport const create = mutation({\n  args: {\n    text: string(),\n  },\n  returns: createResultValidator,\n  handler: async (ctx, args) => {\n    const userId = await getRequiredUserId(ctx);\n    const text = args.text.trim();\n    if (!text) {\n      throw new Error("Todo text cannot be empty");\n    }\n    if (text.length > MAX_TODO_TEXT_LENGTH) {\n      throw new Error(`Todo text must be ${MAX_TODO_TEXT_LENGTH} characters or fewer`);\n    }\n\n    const existingTodos = await ctx.db\n      .query("todos")\n      .withIndex("by_user_created_at", (q) => q.eq("userId", userId))\n      .order("desc")\n      .take(MAX_TODOS_PER_USER);\n    if (existingTodos.length >= MAX_TODOS_PER_USER) {\n      throw new Error(`Todo limit reached: keep at most ${MAX_TODOS_PER_USER} todos`);\n    }\n\n    await ctx.db.insert("todos", {\n      userId,\n      text,\n      done: false,\n      createdAt: Date.now(),\n    });\n    return null;\n  },\n});\n\nexport const toggle = mutation({\n  args: {\n    id: id("todos"),\n  },\n  returns: toggleResultValidator,\n  handler: async (ctx, args) => {\n    const userId = await getRequiredUserId(ctx);\n    const todo = await ctx.db.get(args.id);\n    if (!todo) {\n      throw new Error("Todo not found");\n    }\n    if (todo.userId !== userId) {\n      throw new Error("Unauthorized");\n    }\n\n    await ctx.db.patch(args.id, {\n      done: !todo.done,\n    });\n    return null;\n  },\n});\n',
    "convex/tsconfig.json":
      '{\n  /* This TypeScript project config describes the environment that\n   * Convex functions run in and is used to typecheck them.\n   * You can modify it, but some settings are required to use Convex.\n   */\n  "compilerOptions": {\n    /* These settings are not required by Convex and can be modified. */\n    "allowJs": true,\n    "strict": true,\n    "moduleResolution": "Bundler",\n    "jsx": "react-jsx",\n    "skipLibCheck": true,\n    "allowSyntheticDefaultImports": true,\n\n    /* These compiler options are required by Convex */\n    "target": "ESNext",\n    "lib": ["ES2023", "dom"],\n    "forceConsistentCasingInFileNames": true,\n    "module": "ESNext",\n    "isolatedModules": true,\n    "noEmit": true\n  },\n  "include": ["./**/*"],\n  "exclude": ["./_generated"]\n}\n',
    "docs/local-setup.md":
      "# Local setup\n\nUse this when you want to run the app from your own computer instead of only\nthrough Cloudflare.\n\n## Install Vite+\n\nOn macOS:\n\n```sh\ncurl -fsSL https://vite.plus | bash\n```\n\nOn Windows PowerShell:\n\n```powershell\nirm https://vite.plus/ps1 | iex\n```\n\nOpen a new terminal after installing Vite+, then install dependencies:\n\n```sh\npnpm install\n```\n\n## Run the app\n\nFrom the repository root:\n\n```sh\npnpm run dev\n```\n\n`pnpm run dev` starts Convex and TanStack Start together. On the first run,\nConvex may ask you to sign in and choose or create a development deployment.\nThe dev script also creates Convex Auth JWT keys in that development deployment\nif they are missing.\n\nOpen the local URL printed by Vite.\n\n## Run worktree mode\n\nUse worktree mode for Codex, Conductor, or a separate git worktree where you\nwant an isolated local backend.\n\n```sh\npnpm run dev:worktree\n```\n\nThis repo's `dev:worktree` script is a TypeScript launcher run by Node instead\nof `CONVEX_AGENT_MODE=anonymous ...` shell syntax, so the same command works on\nPowerShell, macOS, and Linux.\n",
